// my — မြန်မာ (birmanês).
//
// A chave é o TEXTO EM PORTUGUÊS, exatamente como aparece no código. O que faltar aqui aparece em
// português, e não como tela vazia.
//
// ---------------------------------------------------------------------------------------------------
// O GÊNERO ESTÁ EM QUEM FALA — É O CASO DO TAILANDÊS, E A MESMA SAÍDA.
//
// A cortesia do birmanês é feita com partículas que declaram o sexo de QUEM FALA: ခင်ဗျာ / ခင်ဗျား
// quando é homem, ရှင် quando é mulher — e as duas servem também de "você". Usar qualquer uma faria o
// próprio aplicativo ter sexo. Não entra nenhuma.
//
// O tom educado vem de **ပါ**, que é neutro e vai no fim dos pedidos e das frases ("ထပ်ကြိုးစားပါ").
// O "você" quase sempre some, que é o natural da língua: o birmanês omite o pronome quando o
// contexto já diz de quem se fala. Onde ele precisa aparecer, é **သင်**, o neutro do texto escrito.
//
// OS BOTÕES levam o verbo com **-ရန်** ("ပို့ရန်", "သိမ်းရန်", "ပယ်ဖျက်ရန်"), que é a forma das
// interfaces em birmanês: "para enviar", e não uma ordem.
// ---------------------------------------------------------------------------------------------------
//
// ALGARISMOS, medidos e não supostos: `Intl.NumberFormat('my').format(1234567)` devolve
// `၁,၂၃၄,၅၆၇`. Então todo número CONTADO numa frase deste arquivo vai em algarismos birmaneses
// (၀၁၂၃၄၅၆၇၈၉), para combinar com o que o Intl escreve ao lado. Identificador técnico (1080p, 512 KB,
// 128×128, H.264, a versão 1.21) fica em 0-9, porque é código e não quantidade.
//
// PONTUAÇÃO PRÓPRIA: o ponto final é **။** e a vírgula é **၊**. O espaço separa frase e oração, não
// palavra — como no tailandês, mas usado com mais liberdade.
//
// FONTE: a escrita birmanesa não vem na fonte do Syden — entra a Noto Sans Myanmar, declarada em
// i18n/idiomas.ts.
//
// VOCABULÁRIO, decidido uma vez: comunidade = အသိုင်းအဝိုင်း, canal = ချန်နယ်, sala de voz =
// အသံအခန်း, chamada = ခေါ်ဆိုမှု, mensagem = မက်ဆေ့ချ်, senha = စကားဝှက်, lixeira = အမှိုက်ပုံး,
// tópico = ခေါင်းစဉ်, conta = အကောင့်, administrador = စီမံသူ, dono = ပိုင်ရှင်, cargo = ရာထူး,
// convite = ဖိတ်ခေါ်ချက်, perfil = ပရိုဖိုင်, transmissão = ထုတ်လွှင့်မှု, recado = အသံ/ဗီဒီယို
// မှတ်စု, soundboard = အသံဘုတ်, vila = ရွာ, guarda-roupa = အဝတ်ဗီရို, tela = မျက်နှာပြင်.
//
// SELO E INSÍGNIA SEPARADOS: selo = တံဆိပ်တုံး (o da comunidade), insígnia = ဆုတံဆိပ် (a da pessoa).

