  'Quando uma mensagem junta estrelas ⭐ suficientes, o Syden a publica no canal de destaques. A estrela de quem escreveu não conta, e apagar a mensagem apaga o destaque.': 'မက်ဆေ့ချ်တစ်ခုသည် ⭐ ကြယ် လုံလောက်စွာ ရလာသောအခါ Syden က ထူးခြားစာများ ချန်နယ်တွင် တင်သည်။ ရေးသူ၏ ကိုယ်ပိုင်ကြယ်ကို မရေတွက်ပါ၊ မက်ဆေ့ချ်ကို ဖျက်လျှင် ထူးခြားစာလည်း ပျက်သွားသည်။',
