  'Mês': 'လ',
  'No dia do aniversário de quem informou a data, o Syden publica os parabéns no canal escolhido. Use {pessoa} no lugar do nome.': 'ရက်စွဲထည့်ထားသူ၏ မွေးနေ့တွင် Syden က ရွေးထားသော ချန်နယ်တွင် ဆုတောင်းစကား တင်သည်။ အမည်နေရာတွင် {pessoa} ကို သုံးပါ။',
