  'Quanto tempo cada pessoa espera entre uma mensagem e outra no canal.': 'ချန်နယ်တွင် မက်ဆေ့ချ်တစ်ခုနှင့်တစ်ခုကြား တစ်ဦးချင်း စောင့်ရမည့်အချိန်။',
  'Regras': 'စည်းမျဉ်းများ',
  'Regras que o Syden aplica sozinho, antes de a mensagem aparecer. Quem administra não passa por elas. A mensagem barrada volta para quem escreveu, com o motivo, e ninguém mais a vê.': 'မက်ဆေ့ချ်မပေါ်ခင် Syden ကိုယ်တိုင် ကျင့်သုံးသော စည်းမျဉ်းများ။ စီမံသူများနှင့် မသက်ဆိုင်ပါ။ ပိတ်ခံရသော မက်ဆေ့ချ်သည် အကြောင်းရင်းနှင့်အတူ ရေးသူထံ ပြန်သွားပြီး အခြားမည်သူမျှ မမြင်ရပါ။',
  'Salvo.': 'သိမ်းပြီးပါပြီ။',
  'Uma por linha. Vale a palavra inteira, sem diferença de acento ou de maiúscula: proibir uma palavra não barra outra mais longa que só a contenha.': 'တစ်ကြောင်းလျှင် တစ်ခု။ စကားလုံးတစ်ခုလုံးကို ရေတွက်သည်၊ အသံထွက်သင်္ကေတ သို့မဟုတ် စာလုံးကြီးကွာခြားမှု မရှိ: စကားလုံးတစ်ခုကို တားမြစ်ခြင်းသည် ၎င်းကို ပါဝင်ရုံသာရှိသော ပိုရှည်သည့် စကားလုံးကို မပိတ်ပါ။',
  '{faltam} pontos para o nível {proximo}.': 'အဆင့် {proximo} အထိ {faltam} မှတ် ကျန်သည်။',
  'Adicionar recompensa': 'ဆုလာဘ် ထည့်ရန်',
