  'Escreva um e-mail válido: é por ele que você confirma a conta.': 'မှန်ကန်တဲ့ အီးမေးလ် ရေးပါ- အကောင့်ကို အဲဒါနဲ့ အတည်ပြုရပါတယ်။',
