  'O que você fez a respeito?': 'ဒီကိစ္စအတွက် ဘာလုပ်ခဲ့လဲ။',
  'O selo aparece aqui quando o primeiro marco cair. Até lá ele fica guardado — e chegar nele é justamente o que ele vai significar.':
    'ပထမမှတ်တိုင် ရောက်တဲ့အခါ တံဆိပ်တုံး ဒီမှာ ပေါ်ပါမယ်။ အဲဒီအထိ သိမ်းထားပါမယ် — အဲဒီကို ရောက်ခြင်းကိုယ်တိုင်က သူ့အဓိပ္ပာယ်ပါ။',
