  'O som chega quando você abre esta transmissão.': 'ဒီထုတ်လွှင့်မှုကို ဖွင့်တဲ့အခါ အသံ ရောက်လာပါမယ်။',
  'O survival do Léo': 'အောင်အောင်ရဲ့ survival ဆာဗာ',
  'O Syden já sabe escrever em qualquer uma destas línguas — falta a tradução dos textos. Enquanto ela não chega, o que não estiver traduzido aparece em português, e as letras de cada alfabeto aparecem certas, sem quadradinhos.':
    'Syden က ဒီဘာသာစကား တစ်ခုခုနဲ့ ရေးနိုင်ပြီးပါပြီ — စာသား ဘာသာပြန်ချက်သာ လိုပါသေးတယ်။ မရောက်သေးခင် ဘာသာမပြန်ရသေးတာက ပေါ်တူဂီလို ပေါ်ပြီး အက္ခရာတိုင်းကို လေးထောင့်ကွက်မပါဘဲ မှန်မှန် ပြပါမယ်။',
  'O Syden vai ficar fora do ar por uns 10 minutos para uma atualização.': 'အပ်ဒိတ်အတွက် Syden ကို မိနစ် ၁၀ ခန့် ပိတ်ထားပါမယ်။',
