    'အောက်ပါ မှတ်တိုင်များကို တစ်ယောက်တည်း မရောက်နိုင်အောင် ရွေးထားပါတယ် — အားလုံးက အချိန်ကြာလာတာနဲ့အမျှ လူတစ်ယောက်ထက် ပိုလိုပါတယ်။',
