  'Ninguém cantou ainda. Conta quando alguém põe uma música com a turma na sala.': "မည်သူမျှ မသီဆိုရသေးပါ။ အဖွဲ့ အခန်းထဲရှိနေစဉ် တစ်ယောက်ယောက် သီချင်းဖွင့်သောအခါ ရေတွက်သည်။",
  'Idiomas': "ဘာသာစကားများ",
  'Idiomas falados': "ပြောသော ဘာသာစကားများ",
  'Idiomas em estudo': "လေ့လာနေသော ဘာသာစကားများ",
  'Aparece no seu cartão de perfil, para quem fala um idioma achar quem o estuda. É opcional.': "သင့်ပရိုဖိုင်ကတ်တွင် ပြသပြီး ဘာသာစကားတစ်ခု ပြောသူက ၎င်းကို လေ့လာနေသူကို ရှာနိုင်စေသည်။ ရွေးချယ်နိုင်သည်။",
  'Feliz aniversário, {nome}!': 'မွေးနေ့ မင်္ဂလာပါ {nome}!',
  'Que este ano venha cheio de boas conversas, boas partidas e boa companhia.': 'ဒီနှစ်ဟာ စကားကောင်းတွေ၊ ဂိမ်းကောင်းတွေ၊ အပေါင်းအသင်းကောင်းတွေနဲ့ ပြည့်နေပါစေ။',
  'Quem abre o site': 'ဆိုက်ကို ဖွင့်သူ',
