  'Também de graça, e também trocáveis quando quiser. Ficam nas configurações da comunidade, porque valem para a comunidade inteira e não só para você.':
    'ဒါတွေလည်း အခမဲ့ဖြစ်ပြီး ကြိုက်တဲ့အချိန် ပြောင်းနိုင်ပါတယ်။ သင့်အတွက်သာမက အသိုင်းအဝိုင်း တစ်ခုလုံးအတွက် ဖြစ်လို့ အသိုင်းအဝိုင်း ဆက်တင်များမှာ ရှိပါတယ်။',
