  'Você foi convidado. É só escolher um nome, um e-mail e uma senha.': 'ဖိတ်ခေါ်ခံရပါပြီ။ အမည်၊ အီးမေးလ်နဲ့ စကားဝှက် ရွေးရုံပါပဲ။',
  'Você não bloqueou ninguém.': 'ဘယ်သူ့ကိုမှ မပိတ်ဆို့ထားပါ။',
