  'Você não votou nesta.': 'ဒီတစ်ခုမှာ မဲမပေးခဲ့ပါ။',
  'Só aquele programa, sem som: o navegador não pega o som de uma janela. Para ir com som, use a tela inteira.': 'ထိုပရိုဂရမ်တစ်ခုတည်း၊ အသံမပါ – ဘရောက်ဇာသည် ဝင်းဒိုး၏ အသံကို မဖမ်းနိုင်ပါ။ အသံပါ ပို့ရန် မျက်နှာပြင်တစ်ခုလုံးကို သုံးပါ။',
  'Na sala de voz, com a turma': 'အသံအခန်းထဲမှာ သူငယ်ချင်းတွေနဲ့',
  'Esperando alguém da sala sentar do outro lado…': 'အခန်းထဲက တစ်ယောက်ယောက် တစ်ဖက်မှာ ထိုင်ဖို့ စောင့်နေပါတယ်…',
  '{nome} quer jogar. Sente do outro lado!': '{nome} ကစားချင်နေပါတယ်။ တစ်ဖက်မှာ ထိုင်လိုက်ပါ!',
  'Sua vez!': 'သင့်အလှည့်!',
