  'Empate!': 'သရေ!',
  'Ninguém sentou para jogar.': 'ဘယ်သူမှ ကစားဖို့ မထိုင်ခဲ့ပါ။',
  '{nome} demorou demais para jogar. {vencedor} venceu!': '{nome} အချိန်ကြာလွန်းသွားပါတယ်။ {vencedor} နိုင်ပါပြီ!',
  '{nome} desistiu. {vencedor} venceu!': '{nome} လက်လျှော့လိုက်ပါတယ်။ {vencedor} နိုင်ပါပြီ!',
