  '{n} de {total} já completaram.': '{total} ယောက်မှာ {n} ယောက် ဖြည့်ပြီးပါပြီ။',
  'Preencha todas as categorias antes de parar.': 'မရပ်ခင် အမျိုးအစားအားလုံးကို ဖြည့်ပါ။',
