  'Stop': 'Stop',
  'Sai uma letra e cada um escreve uma palavra com ela em cada categoria. Quem completar primeiro aperta STOP, e a turma decide o que vale.': 'စာလုံးတစ်လုံး ထွက်လာပြီး လူတိုင်းက အမျိုးအစားတိုင်းမှာ အဲဒီစာလုံးနဲ့ စတဲ့ စကားလုံး ရေးရပါတယ်။ အရင်ဆုံး ဖြည့်ပြီးသူက STOP နှိပ်ပြီး ဘာက ရေတွက်မလဲဆိုတာ သူငယ်ချင်းတွေက ဆုံးဖြတ်ပါတယ်။',
  'Sudoku': 'ဆူဒိုကူ',
  'Todo mundo recebe o mesmo sudoku, e a sala vê quem está mais perto de terminar.': 'လူတိုင်း တူညီတဲ့ ဆူဒိုကူကို ရပြီး ဘယ်သူ ပြီးခါနီးလဲဆိုတာ အခန်းက မြင်ရပါတယ်။',
