  'Duas pessoas põem pedras no tabuleiro, uma de cada vez. Vence quem fizer cinco seguidas. A sala assiste.': 'နှစ်ယောက် တစ်လှည့်စီ ဘုတ်ပေါ်မှာ ကျောက်ချပါတယ်။ ငါးလုံး တန်းအောင် ချနိုင်သူ နိုင်ပါတယ်။ အခန်းက ကြည့်နေပါတယ်။',
  'Mancala': 'မန်ကာလာ',
  'O jogo de semear: pegue as sementes de uma casa e espalhe uma por casa. Vence quem guardar mais no depósito. A sala assiste.': 'မျိုးစေ့ကြဲတဲ့ ဂိမ်း- တွင်းတစ်တွင်းက မျိုးစေ့တွေကို ယူပြီး နောက်တွင်းတွေထဲ တစ်စေ့စီ ကြဲပါ။ ကိုယ့်ဂိုဒေါင်ထဲ ပိုများများ စုနိုင်သူ နိုင်ပါတယ်။ အခန်းက ကြည့်နေပါတယ်။',
