  'Já tem uma partida acontecendo nesta sala.': 'ဒီအခန်းမှာ ပွဲတစ်ပွဲ ကစားနေပြီးသားပါ။',
  'Só quem começou a partida pode encerrá-la antes do fim.': 'ပွဲစတင်သူသာ မပြီးခင် ရပ်နိုင်ပါတယ်။',
  'Lobisomem': 'ဝံပုလွေလူ',
  'À noite, escolha com os outros lobisomens quem atacar. De dia, não deixe ninguém desconfiar.': 'ညဘက်မှာ တခြား ဝံပုလွေလူတွေနဲ့အတူ ဘယ်သူ့ကို တိုက်မလဲ ရွေးပါ။ နေ့ဘက်မှာ ဘယ်သူမှ မသင်္ကာအောင် နေပါ။',
  'Vidente': 'အနာဂတ်မြင်သူ',
  'À noite, descubra se alguém é lobisomem. Conte de dia, se achar que vale o risco.': 'ညဘက်မှာ တစ်ယောက်ယောက်က ဝံပုလွေလူ ဟုတ်မဟုတ် စုံစမ်းပါ။ စွန့်စားရကျိုးနပ်တယ်ထင်ရင် နေ့ဘက်မှာ ပြောပါ။',
  'Anjo': 'ကောင်းကင်တမန်',
  'À noite, escolha alguém para proteger. Se os lobisomens atacarem essa pessoa, ela sobrevive.': 'ညဘက်မှာ ကာကွယ်ပေးမယ့်သူ တစ်ယောက်ကို ရွေးပါ။ ဝံပုလွေလူတွေက အဲဒီလူကို တိုက်ရင်တောင် အသက်ရှင်ပါတယ်။',
  'Da vila': 'ရွာက လူ',
  'À noite, durma. De dia, descubra quem são os lobisomens e vote para tirá-los do jogo.': 'ညဘက်မှာ အိပ်ပါ။ နေ့ဘက်မှာ ဘယ်သူတွေက ဝံပုလွေလူလဲ ရှာပြီး ဂိမ်းထဲက ထုတ်ဖို့ မဲပေးပါ။',
  'A vila venceu!': 'ရွာက နိုင်သွားပြီ!',
  'Os lobisomens venceram!': 'ဝံပုလွေလူတွေ နိုင်သွားပြီ!',
  'Noite {n}. A vila dorme.': 'ည {n}။ ရွာ အိပ်နေပါပြီ။',
  'Os lobisomens atacaram {nome} durante a noite.': 'ညတုန်းက ဝံပုလွေလူတွေ {nome} ကို တိုက်ခဲ့တယ်။',
  'Ninguém morreu esta noite.': 'ဒီည ဘယ်သူမှ မသေပါဘူး။',
  'Dia {n}. Conversem e votem em quem vocês acham que é lobisomem.': 'နေ့ {n}။ စကားပြောပြီး ဝံပုလွေလူလို့ ထင်တဲ့သူကို မဲပေးကြပါ။',
  'A vila tirou {nome} do jogo.': 'ရွာက {nome} ကို ဂိမ်းထဲက ထုတ်လိုက်ပြီ။',
  'Empate: ninguém sai hoje.': 'မဲတူ- ဒီနေ့ ဘယ်သူမှ မထွက်ရပါဘူး။',
  'Clique em quem os lobisomens vão atacar.': 'ဝံပုလွေလူတွေ တိုက်မယ့်သူကို နှိပ်ပါ။',
  'Você já usou a sua visão esta noite.': 'ဒီည အမြင်ကို သုံးပြီးသွားပါပြီ။',
  'Clique em alguém para descobrir se é lobisomem.': 'ဝံပုလွေလူ ဟုတ်မဟုတ် သိဖို့ တစ်ယောက်ယောက်ကို နှိပ်ပါ။',
  'Clique em quem você quer proteger esta noite.': 'ဒီည ကာကွယ်ချင်တဲ့သူကို နှိပ်ပါ။',
  'Durma. Os outros papéis estão agindo.': 'အိပ်ပါ။ တခြား အခန်းကဏ္ဍတွေ လုပ်ဆောင်နေပါတယ်။',
  'Você saiu do jogo. Agora só assiste — sem contar nada!': 'ဂိမ်းထဲက ထွက်သွားပါပြီ။ အခု ကြည့်ရုံပဲ — ဘာမှ မပြောနဲ့နော်!',
  'Clique em quem você quer tirar do jogo. O mais votado sai; empate, ninguém.': 'ဂိမ်းထဲက ထုတ်ချင်တဲ့သူကို နှိပ်ပါ။ မဲအများဆုံးရသူ ထွက်ရပါမယ်၊ မဲတူရင် ဘယ်သူမှ မထွက်ရပါဘူး။',
  'é lobisomem': 'ဝံပုလွေလူ',
  'não é lobisomem': 'ဝံပုလွေလူ မဟုတ်',
  'Ninguém hoje': 'ဒီနေ့ ဘယ်သူမှ မရွေး',
  'A solução do problema.': 'ပုစ္ဆာရဲ့ အဖြေ။',
  'Acertou! Agora é torcer pelos outros.': 'မှန်တယ်! အခု တခြားသူတွေကို အားပေးလိုက်ပါ။',
  'Esse não era o lance. Espere a solução.': 'အဲဒီ ရွှေ့ကွက် မဟုတ်ပါဘူး။ အဖြေကို စောင့်ပါ။',
  'Você joga com as brancas. Ache o melhor lance.': 'အဖြူနဲ့ ကစားနေပါတယ်။ အကောင်းဆုံး ရွှေ့ကွက်ကို ရှာပါ။',
  'Você joga com as pretas. Ache o melhor lance.': 'အမည်းနဲ့ ကစားနေပါတယ်။ အကောင်းဆုံး ရွှေ့ကွက်ကို ရှာပါ။',
  'Ver este problema no Lichess': 'ဒီပုစ္ဆာကို Lichess မှာ ကြည့်ရန်',
  'Problema do Lichess · nota {nota}': 'Lichess ပုစ္ဆာ · အဆင့် {nota}',
  'Cada um recebe um papel em segredo. À noite os lobisomens atacam; de dia a vila conversa e vota em quem tirar do jogo. Precisa de 4 pessoas ou mais.': 'လူတိုင်း လျှို့ဝှက် အခန်းကဏ္ဍ တစ်ခုစီ ရပါတယ်။ ညဘက် ဝံပုလွေလူတွေ တိုက်ပြီး နေ့ဘက် ရွာက စကားပြောကာ ဘယ်သူ့ကို ဂိမ်းထဲက ထုတ်မလဲ မဲပေးပါတယ်။ ၄ ယောက် သို့မဟုတ် ပိုလိုပါတယ်။',
  'Problemas de xadrez': 'စစ်တုရင် ပုစ္ဆာများ',
  'Todo mundo recebe o mesmo problema do Lichess. Quem achar o lance certo mais rápido ganha o ponto extra.': 'လူတိုင်း တူညီတဲ့ Lichess ပုစ္ဆာကို ရပါတယ်။ မှန်တဲ့ ရွှေ့ကွက်ကို အမြန်ဆုံး ရှာတွေ့သူ အပိုအမှတ် ရပါတယ်။',
  'Os problemas de xadrez não estão no servidor.': 'စစ်တုရင် ပုစ္ဆာတွေ ဆာဗာမှာ မရှိပါဘူး။',
