  'Palavra secreta': 'လျှို့ဝှက်စကားလုံး',
  'Todo mundo tenta adivinhar a mesma palavra de 5 letras, em 6 chutes. A sala vê as cores dos outros, mas não as letras. Quem acertar com menos chutes ganha mais pontos.': 'လူတိုင်း စာလုံး ၅ လုံးပါတဲ့ စကားလုံးတစ်လုံးတည်းကို ၆ ကြိမ်အတွင်း ခန့်မှန်းကြပါတယ်။ တခြားသူတွေရဲ့ အရောင်ကို မြင်ရပေမဲ့ စာလုံးကို မမြင်ရပါဘူး။ ခန့်မှန်းတဲ့ အကြိမ်နည်းလေ အမှတ်များလေ ဖြစ်ပါတယ်။',
  'A palavra era: {palavra}': 'စကားလုံးက {palavra} ပါ။',
  'Acabaram os seus chutes. Espere a palavra.': 'ခန့်မှန်းခွင့် ကုန်သွားပါပြီ။ စကားလုံးကို စောင့်ပါ။',
  'Escreva uma palavra de 5 letras e aperte Enter.': 'စာလုံး ၅ လုံးပါတဲ့ စကားလုံး ရိုက်ပြီး Enter နှိပ်ပါ။',
