  'Cargos por reação': 'တုံ့ပြန်မှုဖြင့် အခန်းကဏ္ဍ',
  'O Syden publica uma mensagem no canal com um emoji para cada cargo. Quem reage ganha o cargo; quem tira a reação, perde.': 'Syden က ချန်နယ်ထဲမှာ အခန်းကဏ္ဍတစ်ခုစီအတွက် အီမိုဂျီတစ်ခုစီပါတဲ့ မက်ဆေ့ချ်ကို တင်ပါတယ်။ တုံ့ပြန်သူက အခန်းကဏ္ဍကို ရပြီး၊ တုံ့ပြန်မှုကို ဖြုတ်သူက ဆုံးရှုံးပါတယ်။',
