  'O arquivo': 'ဖိုင်',
  '{tipo} «{item}» ({onde}) saiu do Syden porque {quem} disse ter os direitos. Se você tinha autorização para publicar, responda aqui contando: a sua resposta vai ser levada em conta. Enquanto isso não ficar claro, fica fora. Os termos explicam como funciona, na seção 4: https://syden.chat/termos.html#direito-autoral': '{tipo} «{item}» ({onde}) ကို Syden မှ ဖယ်ရှားလိုက်ပါပြီ၊ {quem} က မူပိုင်ခွင့် ရှိတယ်လို့ ပြောလို့ပါ။ ထုတ်ဝေခွင့် ရှိခဲ့ရင် ဒီမှာ ပြန်စာရေးပြီး ရှင်းပြပါ- သင့်အဖြေကို ထည့်သွင်းစဉ်းစားပါမယ်။ ရှင်းလင်းသွားတဲ့အထိ ဖယ်ထားပါမယ်။ ဘယ်လို အလုပ်လုပ်လဲဆိုတာ စည်းမျဉ်းများ အပိုင်း 4 မှာ ရှင်းပြထားပါတယ်- https://syden.chat/termos.html#direito-autoral',
