  'Quem tem o direito escreve para direitos@syden.chat dizendo o que é e onde está. Procure pelo nome, retire, e quem subiu recebe o aviso numa conversa com você, onde pode contestar.': 'မူပိုင်ခွင့်ရှင်က direitos@syden.chat ကို ဘာလဲ၊ ဘယ်မှာလဲ ရေးပို့ပါတယ်။ အမည်နဲ့ ရှာပြီး ဖယ်ရှားပါ၊ တင်ခဲ့သူက သင်နဲ့ စကားဝိုင်းထဲမှာ အသိပေးချက် ရပြီး အဲဒီမှာ ကန့်ကွက်နိုင်ပါတယ်။',
