  'Limite de uso por dia (minutos; vazio é sem limite)': 'တစ်ရက်လျှင် အသုံးပြုချိန် ကန့်သတ်ချက် (မိနစ်; အလွတ်ဆိုလျှင် ကန့်သတ်ချက်မရှိ)',
