  'Motivo:': 'အကြောင်းပြချက်-',
  'Na conta dele, em Configurações → Família, aparece um código. Digite aqui.': 'သူ၏အကောင့်ရှိ ဆက်တင်များ → မိသားစု တွင် ကုဒ်တစ်ခု ပေါ်လာသည်။ ဤနေရာတွင် ရိုက်ထည့်ပါ။',
  'Não deu para gerar o arquivo agora. Tente de novo.': 'ယခု ဖိုင်ကို ဖန်တီး၍မရပါ။ ထပ်ကြိုးစားပါ။',
