  'O limite combinado com o seu responsável é de {n} minutos por dia. Amanhã, o Syden abre de novo.': 'သင့်အုပ်ထိန်းသူနှင့် သဘောတူထားသော ကန့်သတ်ချက်မှာ တစ်ရက် {n} မိနစ် ဖြစ်သည်။ မနက်ဖြန် Syden ပြန်ဖွင့်မည်။',
  'O motivo (a pessoa vai ler)': 'အကြောင်းပြချက် (ထိုသူ ဖတ်ရမည်)',
  'O seu recurso foi recebido em {quando}. Quem cuida do Syden vai ler e responder.': 'သင့်အယူခံကို {quando} တွင် လက်ခံရရှိသည်။ Syden ကို စောင့်ရှောက်သူများက ဖတ်ပြီး ပြန်ဖြေမည်။',
  'O seu responsável': 'သင့်အုပ်ထိန်းသူ',
  'O seu tempo de hoje acabou': 'ယနေ့အတွက် သင့်အချိန် ကုန်သွားပြီ',
  'O Syden é para quem tem 13 anos ou mais.': 'Syden သည် အသက် ၁၃ နှစ်နှင့်အထက် အတွက်ဖြစ်သည်။',
  'O Syden é para quem tem 13 anos ou mais. Ninguém vê a sua data.': 'Syden သည် အသက် ၁၃ နှစ်နှင့်အထက် အတွက်ဖြစ်သည်။ သင့်ရက်စွဲကို မည်သူမျှ မမြင်ရပါ။',
  'O Syden passou a pedir a idade de todo mundo, para proteger quem tem menos de 18 anos (a lei do ECA Digital). Ninguém vê a sua data: só a faixa de idade é usada.': 'အသက် ၁၈ နှစ်အောက်သူများကို ကာကွယ်ရန် Syden သည် ယခု လူတိုင်း၏ အသက်ကို မေးသည် (ECA Digital ဥပဒေ)။ သင့်ရက်စွဲကို မည်သူမျှ မမြင်ရပါ- အသက်အုပ်စုကိုသာ အသုံးပြုသည်။',
  'Para quem foi comunicado e o protocolo (ex.: SaferNet 123)': 'မည်သူ့ထံ အကြောင်းကြားခဲ့သည်နှင့် ပရိုတိုကော (ဥပမာ- SaferNet 123)',
  'Por segurança, a prévia das transmissões fica fechada para menores de idade.': 'လုံခြုံရေးအတွက် အရွယ်မရောက်သေးသူများအတွက် ထုတ်လွှင့်မှု အစမ်းကြည့်ခြင်းကို ပိတ်ထားသည်။',
  'Por segurança, menores de idade conversam no particular só com amigos.': 'လုံခြုံရေးအတွက် အရွယ်မရောက်သေးသူများသည် သူငယ်ချင်းများနှင့်သာ သီးသန့်စကားပြောနိုင်သည်။',
